using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

/// <summary>Tools available to the research agent.</summary>
public static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Uses DuckDuckGo instant-answer API (no key required) for demonstration.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";

        try
        {
            var json = await _http.GetStringAsync(url);
            // Return raw JSON; the model will interpret relevant fields.
            return string.IsNullOrWhiteSpace(json) ? "No results found." : json;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string SaveNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

// --- Main Program ---

Console.WriteLine("=== AI Research Agent ===\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"Researching topic: \"{topic}\"\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different angles).
        2. Saving key findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes and produce a final summary.

        Be thorough: perform at least 2-3 searches, save important findings, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
];

Console.WriteLine("Agent is working...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

